def write_new(path, contents):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        raise FileExistsError("NO_OVERWRITE: " + str(path))
    with path.open("x", encoding="utf-8") as f:
        f.write(contents)

